#include <stdbool.h>
static int R[9],C[9],B[9];static bool solve(char**b,int pos){if(pos==81)return true;int i=pos/9,j=pos%9;if(b[i][j]!='.')return solve(b,pos+1);int k=i/3*3+j/3,used=R[i]|C[j]|B[k];for(int d=0;d<9;d++){int bit=1<<d;if(!(used&bit)){b[i][j]='1'+d;R[i]|=bit;C[j]|=bit;B[k]|=bit;if(solve(b,pos+1))return true;R[i]^=bit;C[j]^=bit;B[k]^=bit;}}b[i][j]='.';return false;}void solveSudoku(char**b,int n,int*cols){for(int i=0;i<9;i++)R[i]=C[i]=B[i]=0;for(int i=0;i<9;i++)for(int j=0;j<9;j++)if(b[i][j]!='.'){int bit=1<<(b[i][j]-'1');R[i]|=bit;C[j]|=bit;B[i/3*3+j/3]|=bit;}solve(b,0);}
